import 'package:stiv/features/diagnostic/models/hypothesis.dart';

// ─────────────────────────────────────────────────────────────────────────────
// HIPÓTESIS DE RED — connectivity_issue
// ─────────────────────────────────────────────────────────────────────────────

const networkConnectivityHypotheses = <Hypothesis>[
  Hypothesis(id: 'ip_conflict', label: 'Conflicto de dirección IP', description: 'Dos o más equipos en la red comparten la misma dirección IP, causando que ambos pierdan conectividad intermitentemente. Ocurre cuando el DHCP asigna una IP que ya tiene un equipo con IP estática mal configurada.', recommendedActions: ['Paso 1 — En el equipo afectado, ejecutar "ipconfig" (Windows) o "ip addr" (Linux) y anotar la IP actual.', 'Paso 2 — Desde otro equipo en la misma red, ejecutar "arp -a" y buscar si hay dos entradas con la misma IP pero distinta MAC: eso confirma conflicto.', 'Paso 3 — Acceder a la interfaz web del router/switch y revisar la tabla DHCP: identificar si hay una IP asignada dos veces.', 'Paso 4 — Asignar al equipo conflictivo una IP estática fuera del rango DHCP (ej. si DHCP usa 192.168.1.100–200, usar 192.168.1.50).', 'Paso 5 — Configurar el DHCP con reservas por MAC address para dispositivos críticos como cámaras y NVR, evitando conflictos futuros.'], escalationThreshold: 0.30),
  Hypothesis(id: 'cable_network_failure', label: 'Falla de cable de red', description: 'El cable UTP tiene un daño físico, mal crimpado, o supera los 100m. Es la causa más frecuente y solucionable. Un cable con un par abierto puede dar conectividad intermitente o velocidad reducida.', recommendedActions: ['Paso 1 — Conectar el cable a un tester de red: todos los pines 1–8 deben encender en secuencia. Si alguno falla, hay un corte o mal crimpado.', 'Paso 2 — Inspeccionar ambos conectores RJ45 bajo luz: los 8 alambres deben verse ordenados y llegar hasta el extremo del conector.', 'Paso 3 — Reemplazar temporalmente por un patchcord conocido como bueno para verificar si el problema desaparece.', 'Paso 4 — Si el cable está dentro de paredes/conduit y no se puede reemplazar de inmediato, instalar un switch intermediario en la mitad del recorrido si la longitud supera los 90m.', 'Paso 5 — Documentar el tendido del cable afectado en el plano de red para programar su reemplazo preventivo.'], escalationThreshold: 0.25),
  Hypothesis(id: 'switch_port_failure', label: 'Puerto del switch dañado o deshabilitado', description: 'El puerto físico del switch está dañado, deshabilitado por política de seguridad (port security), o en estado de error-disabled por detección de bucle (STP) o violación de MAC.', recommendedActions: ['Paso 1 — Conectar el equipo a un puerto diferente del switch y verificar si la conectividad se restaura.', 'Paso 2 — Desde la consola del switch, ejecutar "show interfaces fa0/X" (Cisco) o equivalente: verificar si el puerto está "err-disabled".', 'Paso 3 — Si el puerto está "err-disabled", ejecutar "shutdown" y luego "no shutdown" para resetear el estado del puerto.', 'Paso 4 — Verificar si el switch tiene "Port Security" habilitado: si el equipo fue reemplazado, la nueva MAC puede estar bloqueada.', 'Paso 5 — Revisar los LEDs del switch: LED ámbar constante en un puerto indica que STP bloqueó el puerto por detección de bucle.'], escalationThreshold: 0.30),
  Hypothesis(id: 'misconfiguration', label: 'Mala configuración IP / VLAN / DNS', description: 'La configuración de red del equipo tiene parámetros incorrectos: IP fuera del segmento, máscara errónea, gateway incorrecto o DNS no configurado. También incluye configuración de VLAN incorrecta en el switch.', recommendedActions: ['Paso 1 — En el equipo afectado, verificar: dirección IP, máscara de subred, puerta de enlace y DNS. Comparar con un equipo que sí funciona en el mismo segmento.', 'Paso 2 — Hacer ping a la puerta de enlace (ej. 192.168.1.1): si no responde, el problema es la IP/gateway. Si responde, el problema puede ser DNS o routing.', 'Paso 3 — Hacer ping a 8.8.8.8 (Google DNS): si responde pero no hay navegación web, el problema es DNS. Cambiar el DNS a 8.8.8.8 o 1.1.1.1.', 'Paso 4 — Si el equipo está en una VLAN específica, verificar en el switch que el puerto esté en el modo correcto (access/trunk) y en la VLAN correcta.', 'Paso 5 — Verificar que el servidor DHCP esté operativo: reiniciar el servicio DHCP o asignar IP estática temporalmente para aislar el problema.'], escalationThreshold: 0.35),
  Hypothesis(id: 'gateway_failure', label: 'Falla del router / gateway', description: 'El router o dispositivo de gateway no está enrutando tráfico correctamente. Puede estar reiniciando por calor, con tabla de enrutamiento corrupta, o con la interfaz WAN caída.', recommendedActions: ['Paso 1 — Verificar el LED de la interfaz WAN del router: debe estar encendido o parpadeando. Si está apagado, hay un problema con el enlace del proveedor.', 'Paso 2 — Reiniciar el router (apagar 30 segundos, encender) y esperar 2 minutos antes de probar conectividad.', 'Paso 3 — Desde un PC conectado directamente al router, hacer ping a la IP WAN y a 8.8.8.8. Si falla el ping a 8.8.8.8, el problema es el enlace WAN o el ISP.', 'Paso 4 — Contactar al ISP con el número de ticket generado. Solicitar verificación de señal en el modem/ONT.', 'Paso 5 — Si el router tiene configuración NAT o firewall, verificar que las reglas no estén bloqueando tráfico interno.'], escalationThreshold: 0.35),
  Hypothesis(id: 'firewall_blocking', label: 'Bloqueo por firewall o ACL', description: 'Una regla de firewall, lista de control de acceso (ACL) o política de seguridad está bloqueando el tráfico del equipo. Muy común después de cambios de red o actualizaciones de firmware.', recommendedActions: ['Paso 1 — Verificar si el equipo puede hacer ping a la puerta de enlace pero no acceder a servicios específicos: eso apunta a bloqueo por firewall.', 'Paso 2 — Revisar las reglas del firewall o ACL en el router/switch: buscar reglas que bloqueen la IP o MAC del equipo afectado.', 'Paso 3 — Temporalmente, deshabilitar el firewall o crear una regla de permiso temporal para la IP del equipo y verificar si se restaura la conectividad.', 'Paso 4 — Revisar el log del firewall para ver si aparecen paquetes rechazados desde la IP del equipo.', 'Paso 5 — Si el equipo fue recientemente movido a otra subred o VLAN, actualizar las reglas del firewall para la nueva ubicación.'], escalationThreshold: 0.40),
  Hypothesis(id: 'wifi_interference', label: 'Interferencia o cobertura WiFi insuficiente', description: 'Si el equipo se conecta por WiFi, la señal puede ser débil por distancia, paredes, interferencia de otros dispositivos o saturación del canal inalámbrico.', recommendedActions: ['Paso 1 — Verificar la potencia de señal WiFi en el equipo: debe estar por encima de -70 dBm para conexión confiable. Debajo de -80 dBm la conexión será inestable.', 'Paso 2 — Usar una app de análisis WiFi para ver qué canales están saturados en 2.4 GHz y cambiar el AP a un canal menos congestionado (1, 6 o 11 en 2.4 GHz).', 'Paso 3 — Si hay muchos equipos WiFi conectados al mismo AP, considerar instalar un AP adicional o usar la banda de 5 GHz para equipos cercanos (mayor velocidad, menor alcance).', 'Paso 4 — Verificar que el equipo no esté usando el mismo canal que redes WiFi vecinas: la interferencia co-canal reduce significativamente el rendimiento.', 'Paso 5 — Para dispositivos críticos de videovigilancia, usar siempre conexión cableada en lugar de WiFi cuando sea posible.'], escalationThreshold: 0.35),
  Hypothesis(id: 'dirty_ethernet_port', label: 'Puerto de red o conector RJ45 sucio o sulfatado', description: 'Los pines de cobre internos del puerto hembra RJ45 o del conector macho están cubiertos de polvo, telarañas o pátina verde (sulfatación por humedad), causando falsos contactos LAN o interrupción del PoE.', recommendedActions: ['Paso 1 — Desconectar el cable RJ45 del equipo e inspeccionar visualmente con una linterna el fondo del puerto. Buscar 8 pelos de cobre alineados y libres de pátina o suciedad.', 'Paso 2 — Si hay corrosión o polvo prensado, usar limpia-contactos dieléctrico en spray (nunca agua ni WD-40 normal) aplicando un chorro directo al puerto apagado.', 'Paso 3 — Frotar iterativamente conectando y desconectando el cable varias veces para arrancar mecánicamente la sulfatación de los pines.', 'Paso 4 — Inspeccionar también la cabeza plástica RJ45 (macho). Si el oro de las cuchillas se ve negro u opaco, cortar y ponchar un plug nuevo.', 'Paso 5 — Si la instalación es en exterior sin la protección IP correcta (prensaestopas pasacables), sellar finalmente con cinta vulcanizante.'], escalationThreshold: 0.20),
  Hypothesis(id: 'mac_filtering_locked', label: 'Bloqueo por seguridad MAC (Port Security)', description: 'El equipo fue cambiado recientemente por mantenimiento, pero el switch administrable bloqueó el puerto automáticamente porque detectó una dirección MAC no autorizada diferente a la original.', recommendedActions: ['Paso 1 — Indagar cronológicamente si el equipo final (Cámara, PC o Biométrico) acaba de ser reemplazado por otro nuevo en la misma roseta/cable.', 'Paso 2 — Revisar el comportamiento del LED del switch en ese puerto. En Cisco y Fortinet, un LED naranja/rojo fijo repentino significa infracción de Port-Security (err-disable state).', 'Paso 3 — Acceder a la consola del switch y listar las violaciones (Show port-security address). Tomar la nueva MAC Address del dispositivo e ingresarla a la lista blanca.', 'Paso 4 — Limpiar la tabla ARP antigua del router/core y aplicar un comando de reseteo del puerto: "shutdown" seguido de "no shutdown".', 'Paso 5 — Si no era equipo nuevo, validar si alguien clonó o está haciendo MAC Spoofing en la red corporativa.'], escalationThreshold: 0.30),
  Hypothesis(id: 'dhcp_pool_exhausted', label: 'Agotamiento del pool DHCP (Saturación de IP)', description: 'La red no puede dar más direcciones IP a los equipos debido a que el rango (Pool DHCP) fue llenado por visitantes temporales, celulares o porque la concesión (Lease Time) es demasiado larga y no recicla IPs.', recommendedActions: ['Paso 1 — Si los equipos pre-existentes fijos tienen red pero los equipos nuevos o reiniciados se quedan sin IP (obteniendo APIPA 169.254.x.x), la sospecha de DHCP es absoluta.', 'Paso 2 — Entrar en la interfaz del Router/Firewall y revisar las "Estadísticas DHCP" o "DHCP Leases". Si el contador "Free" está en 0, estamos sin IP.', 'Paso 3 — Bajar el tiempo de concesión (DHCP Lease Time) de 24 horas a 2-4 horas (o 30 minutos para redes de invitados como hoteles/aeropuertos).', 'Paso 4 — Modificar la máscara de subred para ampliar el Scope o limpiar manualmente las concesiones expiradas atoradas (Clear DHCP bindings).', 'Paso 5 — Sugerencia: pasar todas las cámaras, controladoras e impresoras a IP Fija (Static) fuera del rango del pool, para que no compitan.'], escalationThreshold: 0.35),
  Hypothesis(id: 'loopback_storm', label: 'Tormenta de broadcast (Bucle de red en switch)', description: 'Alguien conectó por accidente ambos extremos de un solo cable de red a dos puertos del mismo switch, o puenteó dos switches redundantes sin protección Spanning-Tree (STP), hundiendo toda la red local.', recommendedActions: ['Paso 1 — Observar todos los LEDs de los switches. Si parpadean locamente, al unísono y a una frecuencia vertiginosa generalizada: ¡hay un bucle activo!', 'Paso 2 — Todos los equipos perderán ping al mismo tiempo en el edificio. Empezar a desconectar cables uno a uno visualmente en el panel mientras se hace PING sostenido al router.', 'Paso 3 — Identificar si hay mini-switches tontos (unmanaged) debajo de los escritorios (cascada) donde los usuarios mezclan sus conexiones.', 'Paso 4 — Activar de inmediato la protección BPDU Guard y RSTP (Rapid Spanning Tree) en la administración de todos los switches corporativos (para evitar que se repita en el futuro).', 'Paso 5 — Aislar el dispositivo causante (una vez descubierto) e instruir al personal sobre no manipular cables no etiquetados.'], escalationThreshold: 0.25),
];
